create function public.finalize_submission(p_id uuid) returns void language plpgsql security invoker set search_path='' as $$ declare r public.submissions;begin select * into r from public.submissions where id=p_id for update;if r.id is null then raise exception 'Not found';end if;if r.status<>'awaiting_upload' then return;end if;insert into public.media(submission_id,original_path) values(r.id,r.photo_path);insert into public.geo_decisions(submission_id,rule) values(r.id,'No verified maintenance responsibility layer; manual review required. Municipal boundary is not an eligibility source.');update public.submissions set status='under_review' where id=r.id;end $$;revoke all on function public.finalize_submission(uuid) from public,anon,authenticated;grant execute on function public.finalize_submission(uuid) to service_role;
